H, W = len(test_input), len(test_input[0])

def rotate90cw(grid):
    return [[grid[H-1-r][c] for r in range(H)] for c in range(W)]

def rotate180(grid):
    return rotate90cw(rotate90cw(grid))

def rotate270cw(grid):
    return rotate90cw(rotate90cw(rotate90cw(grid)))

output = []
for r in range(2*H):
    row_out = []
    for c in range(2*W):
        if r < H and c < W:
            val = test_input[r][c]
        elif r < H and c >= W:
            val = rotate90cw(test_input)[r][c-W]
        elif r >= H and c < W:
            val = rotate270cw(test_input)[r-H][c]
        else:
            val = rotate180(test_input)[r-H][c-W]
        row_out.append(val)
    output.append(row_out)

